const { Kafka } = require('kafkajs');

const kafka = new Kafka({ clientId: 'monitor', brokers: ['localhost:9092'] });
const admin = kafka.admin();

async function checkLag() {
  await admin.connect();

  const groupId = 'order-processors';
  const topic = 'orders';

  const consumerGroup = await admin.describeConsumerGroups({
    groups: [groupId]
  });

  const offsets = await admin.fetchTopicOffsetsByTimestamp(topic, Date.now());
  const groupOffsets = await admin.fetchConsumerGroupOffsets(groupId, topic);

  for (const [partition, groupOffset] of Object.entries(groupOffsets.offsets)) {
    const topicOffset = offsets.find(o => o.partition === Number(partition));
    const lag = topicOffset.high - groupOffset.offset;
    console.log(`Partition ${partition}: lag = ${lag}`);
  }

  await admin.disconnect();
}

checkLag();
